import type { ComponentType } from "react";

import type { IconProps } from "./material-symbols";
import { siteIconPaths, type SiteIconName } from "./site-icons.generated";
import { SvgPathIcon } from "./svg-path-icon";

/**
 * Name → component map so content files stay serializable (and Sanity-ready). Keys are Material
 * Symbols names (the layer names in the Figma file). The set is generated by
 * scripts/generate-site-icons.mjs (user request 2026-10-27: "much more icons", option A); every
 * Sanity icon field offers the same names (sanity/components/icon-picker-input.tsx).
 *
 * Server components only: this pulls in every icon path. Client components get the path from their
 * server parent (`siteIconPath`) and render <SvgPathIcon>, so the browser bundle stays small.
 */
export type IconName = SiteIconName;

function make(name: IconName) {
  const d = siteIconPaths[name];
  function SiteIcon(props: IconProps) {
    return <SvgPathIcon d={d} {...props} />;
  }
  SiteIcon.displayName = `Icon(${name})`;
  return SiteIcon;
}

export const iconRegistry = Object.fromEntries(
  (Object.keys(siteIconPaths) as IconName[]).map((name) => [name, make(name)]),
) as Record<IconName, ComponentType<IconProps>>;

export const isIconName = (name: unknown): name is IconName =>
  typeof name === "string" && Object.hasOwn(siteIconPaths, name);

/** Path data for a client component (see above). Unknown names (old CMS values) → undefined. */
export const siteIconPath = (name: unknown): string | undefined =>
  isIconName(name) ? siteIconPaths[name] : undefined;

export function Icon({ name, ...props }: IconProps & { name: IconName }) {
  // Names come from the CMS: an unknown one renders nothing instead of crashing the page.
  const d = siteIconPath(name);
  return d ? <SvgPathIcon d={d} {...props} /> : null;
}
